import { readdir, readFile, writeFile } from "node:fs/promises";
const root = new URL("../bundle/", import.meta.url);
const paths = (await readdir(root, { recursive: true }))
  .filter((path) => /\.ya?ml$/.test(path))
  .sort();
const files = Object.fromEntries(
  await Promise.all(paths.map(async (path) => [path, await readFile(new URL(path, root), "utf8")])),
);
await writeFile(
  new URL("../../shared/src/bundle.generated.ts", import.meta.url),
  `// ---\n// relationships:\n//   implements: default-process\n// ---\n// Generated by scripts/generate-bundle.mjs.\nexport const bundledFiles = ${JSON.stringify(files, null, 2)} as const;\n`,
);
